window.RP_SESSION={"id":"S-302fcc4667f7","messages":[{"id":"RP-0247882","time":"2026-08-24T12:04:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"흠흠.","characters":["P-b6d81d634c6e"]},{"id":"RP-0247883","time":"2026-08-24T12:04:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"흠··· 흠.","characters":["P-b6d81d634c6e"]},{"id":"RP-0247884","time":"2026-08-24T12:05:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"마리우스는 오늘 아침, 맥스와 많은 이야기를 나눴습니다. 헬리오스와의 일들, 그간 있었던 일들. 그리고 검을 다시금 잡을 수 있게된 계기.","characters":["P-b6d81d634c6e"]},{"id":"RP-0247885","time":"2026-08-24T12:05:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"······ 동-시에 연인에 대해서도 말하기는 했지요.","characters":["P-b6d81d634c6e"]},{"id":"RP-0247886","time":"2026-08-24T12:07:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"요즘은 기분이 좋습니다. 너무 좋아서 이상할 정도로요.","characters":["P-b6d81d634c6e"]},{"id":"RP-0247887","time":"2026-08-24T12:07:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"딱히 이상한 일도 벌어지지 않고, 평온합니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-0247888","time":"2026-08-24T12:07:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"— 이대로가 이어질 수 있으면 좋겠다고 생각했어요.","characters":["P-b6d81d634c6e"]},{"id":"RP-0247889","time":"2026-08-24T12:08:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"그러나 요즘 이상한 꿈을 안 꾼다고는 답할 수 없을 것 같아요.","characters":["P-b6d81d634c6e"]},{"id":"RP-0247890","time":"2026-08-24T12:09:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"!힘","characters":["P-b6d81d634c6e"]},{"id":"RP-0247891","time":"2026-08-24T12:09:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'마리우스'의 힘 판정 :\n[5] + [4] = [9]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-0247892","time":"2026-08-24T12:09:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"쿵, 도끼가 가볍게 나무를 내리찍습니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-0247893","time":"2026-08-24T12:09:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"산 속 깊은 곳. 은은한 공기를 느끼고자 온 곳에서 마리우스는 과거를 회상했습니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-0247894","time":"2026-08-24T12:10:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"그러나 여전히 — 과거와 다르다고 하더라도 — 마리우스는 문제점을 가지고 있었습니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-0247895","time":"2026-08-24T12:10:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"너울을 하나 넘었음에도 또 너울 하나가 다가오는 삶이 지쳤다고 생각하자마자, 뭔가 큰 것이, 긴 시간 동안 쉰만큼 더더욱 무거운 것이 다가오는 듯한 느낌을 받았으니까요.","characters":["P-b6d81d634c6e"]},{"id":"RP-0247896","time":"2026-08-24T12:10:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"!힘","characters":["P-b6d81d634c6e"]},{"id":"RP-0247897","time":"2026-08-24T12:10:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'마리우스'의 힘 판정 :\n[12] + [4] = [16]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-0247898","time":"2026-08-24T12:11:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"쿵. 강하게 도끼가 나무를 또 내려찍습니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-0247899","time":"2026-08-24T12:11:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"마리우스가 쪼개진 나무를 바라봅니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-0247900","time":"2026-08-24T12:11:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"꿈자리가 좋지 않아요.\n\n마르테우스와 소통한 이후부터, 더욱.","characters":["P-b6d81d634c6e"]},{"id":"RP-0247901","time":"2026-08-24T12:12:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"기억하고 싶은데, 무언가 구름이 낀 것처럼 제대로 생각나지 않아요.","characters":["P-b6d81d634c6e"]},{"id":"RP-0247902","time":"2026-08-24T12:17:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"To be Honored\nTo be Remembered\nTo be Recognized\nTo be Seen","characters":["P-b6d81d634c6e"]},{"id":"RP-0247903","time":"2026-08-24T12:17:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"무거운 목소리로 읊어내는 그 네 문장.","characters":["P-b6d81d634c6e"]},{"id":"RP-0247904","time":"2026-08-24T12:17:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"그것들을 제외하고서는···. 잘 모르겠어요.","characters":["P-b6d81d634c6e"]},{"id":"RP-0247905","time":"2026-08-24T12:17:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-b6d81d634c6e"]},{"id":"RP-0247906","time":"2026-08-24T12:17:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"다음을 기대할게..!","characters":[]}]};
